INSERT INTO games (id, title, version, lifecycle, source_status, multiplayer_status, manifest_json) VALUES ('royal-ballistix', 'Royal Ballistix', '0.9.0', 'intake', 'awaiting-import', 'not-integrated', '{"id":"royal-ballistix","title":"Royal Ballistix","aliases":["Ballistix","Beach Siege","Royal Ballistix Beach Siege"],"tags":["physics","ball-deflection","survival","arcade"],"description":"Defend a radial gate, capture balls with a magnet and counterattack with Pulse. The v0.9 ten-player source and phone multiplayer integration are pending import.","players":{"min":2,"max":10},"version":"0.9.0","source":{"status":"awaiting-import","paths":[],"provenance":"Known source at CALLBACK commit 50e349b39f2ec458f3e90e7c400464cc2b064ddd; not copied into this repository.","url":"https://github.com/edmondsonedits/CALLBACK/blob/50e349b39f2ec458f3e90e7c400464cc2b064ddd/game-modes/royal-ballistix/index.html"},"lifecycle":"intake","multiplayer":{"status":"not-integrated","evidence":[]}}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, version=excluded.version, lifecycle=excluded.lifecycle, source_status=excluded.source_status, multiplayer_status=excluded.multiplayer_status, manifest_json=excluded.manifest_json;
