INSERT INTO games (id, title, version, lifecycle, source_status, multiplayer_status, manifest_json) VALUES ('royal-sumo', 'Royal Sumo', '0.19.0', 'intake', 'awaiting-import', 'not-integrated', '{"id":"royal-sumo","title":"Royal Sumo","aliases":["Sumo","Royal Sumo Crownfall"],"tags":["arena","physics","sumo","arcade"],"description":"A shrinking-arena sumo game with Bash, Dash and crown-based rounds. The v0.19 ten-player HTML attachment is pending; gameplay and phone multiplayer are not present here.","players":{"min":2,"max":10},"version":"0.19.0","source":{"status":"awaiting-import","paths":[],"provenance":"The chat-mentioned royal_sumo_crownfall_v0.19_10players.html attachment is not available in this repository.","url":null},"lifecycle":"intake","multiplayer":{"status":"not-integrated","evidence":[]}}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, version=excluded.version, lifecycle=excluded.lifecycle, source_status=excluded.source_status, multiplayer_status=excluded.multiplayer_status, manifest_json=excluded.manifest_json;
INSERT INTO games (id, title, version, lifecycle, source_status, multiplayer_status, manifest_json) VALUES ('royal-twisted', 'Royal Twisted', '0.5.0', 'experimental', 'imported', 'not-integrated', '{"id":"royal-twisted","title":"Royal Twisted","aliases":["Spiral Keep","Twisted System-style"],"tags":["reaction","survival","obstacle-dodge","physics","arcade"],"description":"A 2–10 contestant reaction-survival game on a medieval spiral tower: jump low rods, duck high rods, survive seven strikes, and recover from hits that knock contestants back down the course. The standalone v0.5 source is imported with bots and local controls; phone-room multiplayer is not yet integrated.","players":{"min":2,"max":10},"version":"0.5.0","source":{"status":"imported","paths":["source/index.html"],"provenance":"Original Royal Twisted v0.5 HTML developed in the user''s ChatGPT CALLBACK project conversation and imported from the complete chat artifact. Gameplay implementation, visuals, UI, procedural audio and characters are original to this project. Three.js r180 is vendored under assets/vendor under its MIT license. The packaged entry changes only the Three.js import from a pinned jsDelivr URL to the vendored local module; gameplay logic is otherwise preserved.","url":null},"lifecycle":"experimental","multiplayer":{"status":"not-integrated","evidence":[]}}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, version=excluded.version, lifecycle=excluded.lifecycle, source_status=excluded.source_status, multiplayer_status=excluded.multiplayer_status, manifest_json=excluded.manifest_json;
